#include <item/ToolRuntime.hpp>
void RecoveredToolCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,
    const std::string& password,const std::string& path,const std::vector<BulkSource>& sources)
{
    using namespace auriga::item;CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);
    Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"recovered tools owned SQL connection");
    auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"recovered-tool-worker").has_value(),"actual recovered tool worker starts");unsigned attempts=0,terminals=0,selfTransitions=0;
    for(unsigned n=0;n<sources.size();++n){
        const auto key=sources[n].grant.key;const auto& row=std::get<ItemToolRow>(catalog->Find(key)->category);const auto& terms=catalog->FindToolProfile(row.profile)->levels[0];
        Check(row.kind==ToolKind::Rod && row.allWaterPools,"original professional rod water admission");
        const ItemOwner owner{ItemOwnerKind::Character,9200u+n};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4},ItemStorageLayout{{owner,ItemStorageKind::Equipment,1},28,1,1}};
        Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"recovered tool owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();unsigned serial=0;bool replay=false;
        const auto op=[&](){++serial;return std::array<std::uint8_t,16>{0xFD,static_cast<std::uint8_t>(n),static_cast<std::uint8_t>(serial)};};
        const auto apply=[&](const ItemCommit& commit){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"recovered tool operation queued");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got && got->write && got->state,"recovered tool write saved and reloaded");replay=got->write->replay;state=*got->state;};
        const auto find=[&](ItemInstanceId id)->const PersistentItem&{const auto it=std::ranges::find(state.items,id,&PersistentItem::id);Check(it!=state.items.end(),"expected recovered tool instance");return *it;};
        const auto relog=[&](){const auto before=state.items;auto session=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,session).value();Check(state.items==before,"recovered tool exact SQL session reload");};
        const auto grant=[&](){const auto ids=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);auto spec=sources[n].grant;spec.tool=ToolInstanceState{terms.requiredPoints ? terms.requiredPoints-1 : 0,50};auto commit=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,spec,ids);Check(commit.has_value(),"actual recovered source grant");apply(*commit);return ids[0];};
        const auto output=[&](const std::string& phase,ItemInstanceId id,const std::vector<std::byte>& service){const auto write=[&](const char* suffix,const std::vector<std::byte>& bytes){std::ofstream f(path+"."+std::to_string(n)+"."+phase+suffix);for(auto b:bytes){const auto v=std::to_integer<unsigned>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"recovered tool packet exported");};const auto wire=EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items);Check(wire && DecodeTypedInventory(*wire,owner).has_value(),"recovered tool inventory native roundtrip");write(".inventory.hex",*wire);write(".details.hex",EncodeTypedItemDetails(*catalog,state.items).value());write(".service.hex",service);CostumeAppearance look{313,state.fence.revision};if(find(id).placement->kind==ItemStorageKind::Equipment){const auto* e=catalog->Find(find(id).key);look.tool=2;look.models[0]=catalog->FindAppearance(*e->base.appearanceProfile)->modelAsset;}std::vector<std::byte> b;for(auto v:EncodeCostumeAppearance(look).value())b.push_back(std::byte(v));write(".appearance.hex",b);};
        ToolRuntimeActor actor{255,0,0,true,false,false,true,true};const auto id=grant();
        const auto info=[&](unsigned status,ToolRuntimeAction action=ToolRuntimeAction::Info){const auto& item=find(id);return EncodeToolRuntime(*catalog,{static_cast<std::uint8_t>(status),255,0,1234,&item,&item,action,987}).value();};
        output("bag",id,info(1));apply(MakeEquipCommit(*catalog,op(),state.fence,state.storages,state.items,id,{255,0,0}).value());
        Check(BuildEquipmentStats(*catalog,owner,state.items)->tool==ToolKind::Rod,"source tool reaches equipped gameplay stats");output("equipped",id,info(1));
        if(!terms.successItem){++terminals;apply(MakeUnequipCommit(*catalog,op(),state.fence,state.storages,state.items,id,{ItemStorageKind::Inventory,1,0}).value());Check(CheckToolRuntime(*catalog,owner,state.items,{id,{},ToolRuntimeAction::Refine,actor,0}).error()==GatheringError::AtMaximum,"source terminal rod cannot refine or reset");relog();output("terminal",id,info(1));continue;}
        if(terms.successItem==key)++selfTransitions;
        auto denied=actor;denied.completedResourceAction=false;Check(!MakeToolRuntimeCommit(*catalog,op(),state.fence,state.storages,state.items,{id,{},ToolRuntimeAction::Practice,denied,1}),"client cannot invent a completed fishing action");
        auto active=actor;active.fishingActive=true;Check(!MakeToolRuntimeCommit(*catalog,op(),state.fence,state.storages,state.items,{id,{},ToolRuntimeAction::Refine,active,1}),"active fishing cannot refine the rod");
        const auto practice=MakeToolRuntimeCommit(*catalog,op(),state.fence,state.storages,state.items,{id,{},ToolRuntimeAction::Practice,actor,terms.practiceNumerator==terms.practiceDenominator ? 0u : 1u}).value();apply(practice.commit);Check(find(id).tool->trainingPoints==terms.requiredPoints,"real completed fishing practice reaches exact source threshold");
        apply(MakeUnequipCommit(*catalog,op(),state.fence,state.storages,state.items,id,{ItemStorageKind::Inventory,1,0}).value());output("ready",id,info(1,ToolRuntimeAction::Refine));
        const auto before=find(id);const auto success=MakeToolRuntimeCommit(*catalog,op(),state.fence,state.storages,state.items,{id,{},ToolRuntimeAction::Refine,actor,terms.refineChanceBp==10000 ? 0u : 1u}).value();apply(success.commit);++attempts;
        Check(find(id).key==*terms.successItem && find(id).tool==ToolInstanceState{} && find(id).id==before.id,"exact source success target and instance-owned practice reset");const auto saved=state.items;apply(success.commit);Check(replay && state.items==saved,"successful refinement replay cannot transform twice");relog();
        output("success",id,EncodeToolRuntime(*catalog,{3,255,success.outcome,1234,&before,&before,ToolRuntimeAction::Refine,987,terms.refineChanceBp==10000 ? 0u : 1u,success.level,success.state,success.afterItem}).value());
        if(terms.refineChanceBp<10000){
            const auto failId=grant();auto full=find(failId); // Factory state is one practice point below the threshold.
            apply(MakeEquipCommit(*catalog,op(),state.fence,state.storages,state.items,failId,{255,0,0}).value());apply(MakeToolRuntimeCommit(*catalog,op(),state.fence,state.storages,state.items,{failId,{},ToolRuntimeAction::Practice,actor,1}).value().commit);apply(MakeUnequipCommit(*catalog,op(),state.fence,state.storages,state.items,failId,{ItemStorageKind::Inventory,1,1}).value());full=find(failId);
            const auto failed=MakeToolRuntimeCommit(*catalog,op(),state.fence,state.storages,state.items,{failId,{},ToolRuntimeAction::Refine,actor,static_cast<std::uint32_t>(terms.refineChanceBp)+1}).value();apply(failed.commit);++attempts;
            Check(terms.failureItem && find(failId).key==*terms.failureItem && find(failId).tool==ToolInstanceState{},"source failure target is explicit, including self transitions");const auto failSaved=state.items;apply(failed.commit);Check(replay && state.items==failSaved,"failure receipt spends practice once");relog();output("failure",failId,EncodeToolRuntime(*catalog,{3,255,failed.outcome,1234,&full,&full,ToolRuntimeAction::Refine,987,static_cast<std::uint32_t>(terms.refineChanceBp)+1,failed.level,failed.state,failed.afterItem}).value());
        }
    }
    store.Stop();std::cout<<"SOURCE_RECOVERED_TOOL_WORKER=SUCCESS sources="<<sources.size()<<" attempts="<<attempts<<" terminals="<<terminals<<" self_transitions="<<selfTransitions<<" checks="<<checks<<std::endl;
}
